_fail = []


def check(cond, msg):
    print(("  ok  " if cond else " FAIL ") + msg)
    if not cond:
        _fail.append(msg)


def main():
    if len(PINS) < 40:
        print(f"js topology-nodes FAILED: всего {len(PINS)} пинов — снимок пуст или урезан")
        return 1
    node = find_node()
    if node is None:
        print("js topology-nodes: SKIPPED — node не найден ни в PATH, ни у менеджеров версий: " + ", ".join(node_search_paths()))
        return 0
    ids = [p[0] for p in PINS]
    dup = {i for i in ids if ids.count(i) > 1}
    if dup:
        print(f"js topology-nodes FAILED: повторяющиеся id пинов: {sorted(dup)}")
        return 1
    body = []
    for pid, setup, expr, _exp, _msg in PINS:
        body.append(f"try {{ reset(); {setup}\n  out[{json.dumps(pid)}] = {expr}; }} catch (e) {{ out[{json.dumps(pid)}] = {{ __threw: String(e && e.message || e) }}; }}")
    probe = PREAMBLE + "\n".join(body) + "\nconsole.log(JSON.stringify(out));\n"
    harness = ROOT / "scripts" / "_js_harness.mjs"
    probe_path = ROOT / "scripts" / ".probe_js_topology_nodes.tmp.mjs"
    probe_path.write_text(probe)
    try:
        env = {**os.environ, "JS_ROOT": str(ROOT / "static" / "js"), "JS_STUBS": STUBS,
               "LANG": "en_US.UTF-8", "LC_ALL": "en_US.UTF-8", "TZ": "UTC"}
        run = subprocess.run(
            [node, "--import", f"data:text/javascript,import {{ register }} from 'node:module'; register('{harness.as_uri()}');",
             str(probe_path)], capture_output=True, text=True, env=env, cwd=ROOT, timeout=120)
    finally:
        probe_path.unlink(missing_ok=True)
    if run.returncode != 0:
        print(run.stdout); print(run.stderr)
        print("js topology-nodes FAILED: node вышел с кодом %d" % run.returncode)
        return 1
    got = json.loads(run.stdout.strip().splitlines()[-1])
    section = ""
    for pid, _setup, _expr, expected, msg in PINS:
        head = pid.split("_", 1)[0]
        if head != section:
            section = head
            print(f"{section}:")
        want = json.loads(expected)
        have = got.get(pid, {"__missing": True})
        ok = have == want
        check(ok, msg if ok else f"{msg}\n        ожидалось {json.dumps(want, ensure_ascii=False)[:300]}\n        получено  {json.dumps(have, ensure_ascii=False)[:300]}")
    print()
    if _fail:
        print(f"FAILED ({len(_fail)}):")
        for f in _fail:
            print("  - " + f.splitlines()[0])
        return 1
    print(f"js topology-nodes OK: настоящий модуль в node, {len(PINS)} пинов карточки ячейки значениями")
    return 0


if __name__ == "__main__":
    sys.exit(main())
